// mem.h — external memory reader (Windows, C++17)
// Reads the view matrix, local player and entity list from a target process.
// Build the reader with the same bitness as the target (x64 for x64 games),
// because pointers are read as uintptr_t.
#pragma once

#ifndef WIN32_LEAN_AND_MEAN
#define WIN32_LEAN_AND_MEAN
#endif
#ifndef NOMINMAX
#define NOMINMAX
#endif
#include <windows.h>
#include <tlhelp32.h>

#include <cstddef>
#include <cstdint>
#include <cwchar>
#include <optional>
#include <vector>

// ---------------------------------------------------------------------------
// Offsets: every value is a placeholder. Fill them in for your target build
// (from an SDK dump, ReClass, or a Cheat Engine structure dissection).
// ---------------------------------------------------------------------------
namespace offsets {
    // Module-relative
    constexpr std::uintptr_t localPlayer = 0x0;   // -> pointer to local player object
    constexpr std::uintptr_t entityList  = 0x0;   // -> first slot of an entity pointer array
    constexpr std::uintptr_t viewMatrix  = 0x0;   // -> float[16]

    constexpr std::size_t entityStride = sizeof(std::uintptr_t); // bytes between list slots
    constexpr int         maxEntities  = 64;

    // Object-relative (from the player object base)
    constexpr std::uintptr_t health     = 0x0;    // int32
    constexpr std::uintptr_t team       = 0x0;    // int32
    constexpr std::uintptr_t origin     = 0x0;    // Vec3 (feet)
    constexpr std::uintptr_t boneMatrix = 0x0;    // -> array of 3x4 bone matrices

    constexpr int         headBone   = 8;         // bone index of the head
    constexpr std::size_t boneStride = 0x30;      // sizeof(3x4 float matrix)

    // true  = D3D/Source-style row-major matrix (translation in m[3], m[7], m[11], m[15])
    // false = column-major (translation in m[12], m[13], m[14], m[15])
    constexpr bool rowMajorMatrix = true;
}

struct Vec3 {
    float x = 0.f, y = 0.f, z = 0.f;
};

struct Mat4 {
    float m[16] = {};
};

struct Player {
    std::uintptr_t addr = 0;
    int  health = 0;
    int  team   = 0;
    Vec3 origin;
    Vec3 head;
};

// ---------------------------------------------------------------------------
// Process handle + raw reads
// ---------------------------------------------------------------------------
class Process {
public:
    Process() = default;
    Process(const Process&) = delete;
    Process& operator=(const Process&) = delete;
    ~Process() { if (handle_) CloseHandle(handle_); }

    bool attach(const wchar_t* exeName, const wchar_t* moduleName) {
        pid_ = findPid(exeName);
        if (!pid_) return false;

        handle_ = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pid_);
        if (!handle_) return false;

        base_ = findModuleBase(pid_, moduleName);
        return base_ != 0;
    }

    bool alive() const {
        DWORD code = 0;
        return handle_ && GetExitCodeProcess(handle_, &code) && code == STILL_ACTIVE;
    }

    bool readRaw(std::uintptr_t addr, void* out, std::size_t size) const {
        SIZE_T got = 0;
        return addr &&
               ReadProcessMemory(handle_, reinterpret_cast<LPCVOID>(addr), out, size, &got) &&
               got == size;
    }

    template <class T>
    T read(std::uintptr_t addr) const {
        T value{};
        readRaw(addr, &value, sizeof(T));
        return value;
    }

    std::uintptr_t base() const { return base_; }
    DWORD pid() const { return pid_; }

private:
    static DWORD findPid(const wchar_t* exeName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return 0;

        PROCESSENTRY32W pe{};
        pe.dwSize = sizeof(pe);
        DWORD pid = 0;
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
            if (_wcsicmp(pe.szExeFile, exeName) == 0) { pid = pe.th32ProcessID; break; }
        }
        CloseHandle(snap);
        return pid;
    }

    static std::uintptr_t findModuleBase(DWORD pid, const wchar_t* moduleName) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        if (snap == INVALID_HANDLE_VALUE) return 0;

        MODULEENTRY32W me{};
        me.dwSize = sizeof(me);
        std::uintptr_t base = 0;
        for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me)) {
            if (_wcsicmp(me.szModule, moduleName) == 0) {
                base = reinterpret_cast<std::uintptr_t>(me.modBaseAddr);
                break;
            }
        }
        CloseHandle(snap);
        return base;
    }

    HANDLE         handle_ = nullptr;
    DWORD          pid_    = 0;
    std::uintptr_t base_   = 0;
};

// ---------------------------------------------------------------------------
// Game-state readers
// ---------------------------------------------------------------------------
inline std::optional<Player> readPlayer(const Process& proc, std::uintptr_t addr) {
    if (!addr) return std::nullopt;

    Player p;
    p.addr   = addr;
    p.health = proc.read<int>(addr + offsets::health);
    p.team   = proc.read<int>(addr + offsets::team);
    p.origin = proc.read<Vec3>(addr + offsets::origin);
    p.head   = p.origin;

    // Head position = translation column of the head bone's 3x4 matrix.
    const auto bones = proc.read<std::uintptr_t>(addr + offsets::boneMatrix);
    float bm[12];
    if (bones && proc.readRaw(bones + offsets::headBone * offsets::boneStride, bm, sizeof(bm))) {
        p.head = { bm[3], bm[7], bm[11] };
    }
    return p;
}

inline std::optional<Player> readLocalPlayer(const Process& proc) {
    return readPlayer(proc, proc.read<std::uintptr_t>(proc.base() + offsets::localPlayer));
}

inline std::vector<Player> readEntityList(const Process& proc, std::uintptr_t localAddr) {
    std::vector<Player> out;
    out.reserve(offsets::maxEntities);

    const std::uintptr_t list = proc.base() + offsets::entityList;
    for (int i = 0; i < offsets::maxEntities; ++i) {
        const auto addr = proc.read<std::uintptr_t>(list + i * offsets::entityStride);
        if (!addr || addr == localAddr) continue;

        if (auto p = readPlayer(proc, addr); p && p->health > 0) out.push_back(*p);
    }
    return out;
}

inline Mat4 readViewMatrix(const Process& proc) {
    Mat4 vm;
    proc.readRaw(proc.base() + offsets::viewMatrix, vm.m, sizeof(vm.m));
    return vm;
}

// Projects a world position to client-area pixels. Returns false if behind the camera.
inline bool worldToScreen(const Mat4& vm, const Vec3& w, float screenW, float screenH,
                          float& sx, float& sy) {
    const float* m = vm.m;
    float cx, cy, cw;
    if (offsets::rowMajorMatrix) {
        cx = m[0]  * w.x + m[1]  * w.y + m[2]  * w.z + m[3];
        cy = m[4]  * w.x + m[5]  * w.y + m[6]  * w.z + m[7];
        cw = m[12] * w.x + m[13] * w.y + m[14] * w.z + m[15];
    } else {
        cx = m[0] * w.x + m[4] * w.y + m[8]  * w.z + m[12];
        cy = m[1] * w.x + m[5] * w.y + m[9]  * w.z + m[13];
        cw = m[3] * w.x + m[7] * w.y + m[11] * w.z + m[15];
    }
    if (cw < 0.01f) return false;

    const float nx = cx / cw;
    const float ny = cy / cw;
    sx = (screenW * 0.5f) + (nx * screenW * 0.5f);
    sy = (screenH * 0.5f) - (ny * screenH * 0.5f);
    return true;
}
